    <div class="clause-p">
      <span class="clause-title">Leave:</span> {{ doc.leave_details }}
    </div>

    <div class="clause-p">
      <span class="clause-title">Notice Period:</span> {{ doc.notice_period_details }}
    </div>

    <div class="clause-p">
      <span class="clause-title">Joining Details:</span> {{ doc.joining_details }}
    </div>

    <div style="margin-top: 22px; font-weight: 600; font-size: 13.5px; color: #000000;">
      Copy of Documents Required at the Time of Joining:
    </div>

    <div style="font-size: 13.2px; line-height: 1.65; margin-top: 10px;">
