<div class="offer-page">
  <div class="page-header">
    <div class="logo-middle-east">
      <span class="logo-text-main">MIDDLE EAST</span>
      <span class="logo-text-sub">TRAVELS & TOURISM</span>
    </div>
    <div class="logo-iata">
      <svg class="iata-svg" viewBox="0 0 100 70" xmlns="http://www.w3.org/2000/svg">
        <circle cx="50" cy="35" r="30" fill="#005a9c" />
        <ellipse cx="50" cy="35" rx="28" ry="12" fill="none" stroke="#ffffff" stroke-width="1.8" />
        <ellipse cx="50" cy="35" rx="14" ry="28" fill="none" stroke="#ffffff" stroke-width="1.8" />
        <line x1="20" y1="35" x2="80" y2="35" stroke="#ffffff" stroke-width="1.8" />
        <rect x="22" y="24" width="56" height="22" rx="4" fill="#005a9c" opacity="0.95" />
        <text x="50" y="41" font-family="'Montserrat', sans-serif" font-size="16" font-weight="900" fill="#ffffff" text-anchor="middle" letter-spacing="1">IATA</text>
      </svg>
    </div>
  </div>

  <div class="page-content">
    <div class="clause-p">
      <span class="clause-title">Acceptance of Offer:</span> {{ doc.acceptance_terms }}
    </div>

    <div class="signatory-box">
      <div>{{ doc.signatory_company_label or "For, Middle East Travels & Tourism" }}</div>
      <div class="signatory-name">{{ doc.hr_signatory_name or "Gopika" }}</div>
      <div>{{ doc.hr_signatory_designation or "HR Consultant" }}</div>
      <div class="signature-svg-container">
        <svg width="140" height="46" viewBox="0 0 140 46">
          <path d="M12,32 Q28,8 42,24 T68,14 T92,28 T115,16 Q125,12 132,24" fill="none" stroke="#1d4ed8" stroke-width="2.2" stroke-linecap="round"/>
          <path d="M32,26 Q42,34 58,30" fill="none" stroke="#1d4ed8" stroke-width="1.8"/>
          <circle cx="36" cy="18" r="2" fill="#1d4ed8"/>
        </svg>
      </div>
      <div style="font-weight: 700; color: #000000;">{{ doc.hr_signatory_title or "Authorized Signatory" }}</div>
    </div>

    <div class="dashed-divider"></div>

    <div style="font-size: 13.5px; line-height: 1.6; margin-bottom: 30px;">
      {{ doc.acceptance_statement or "I accept the offer of employment with the terms and conditions as mentioned in the offer letter." }}
    </div>

    <table class="acceptance-grid">
      <tr>
        <td style="width: 50%;"><strong>Name:</strong></td>
        <td style="width: 50%;"><strong>Date:</strong></td>
      </tr>
      <tr>
        <td style="width: 50%;"><strong>Signature:</strong></td>
        <td style="width: 50%;"><strong>Place:</strong></td>
      </tr>
    </table>
  </div>

  <div class="page-footer">
    <div class="footer-address">Shobha Tower, 5/3412L, Mavoor Rd, near Emerald Mall, Arayidathupalam, Kozhikode, Kerala 673004</div>
    <div class="footer-contact">Tel: 91 8593944666, 91 7025144666</div>
    <div class="footer-web">info@middleeasttravels.in | www.middleeasttravels.in</div>
  </div>
